import {voiceCapture,voiceDescription,preferVoiceCodec,tuneVoiceSender} from './voice-quality.mjs';
import {VoiceLevels} from './voice-levels.mjs';
const uid=()=>crypto.randomUUID().replaceAll('-','');
const icon=on=>`<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>${on?'':'<path d="m3 3 18 18"/>'}</svg>`;
export class RoomVoice{
 constructor(rooms){this.rooms=rooms;this.alive=true;this.muted=true;this.peers=new Map();this.seen=new Set();this.out=[];this.session=uid();this.levels=new VoiceLevels();this.members=[];this.pagehide=()=>this.destroy();window.addEventListener('pagehide',this.pagehide)}
 attach(button){this.button=button;button.onclick=()=>this.toggle();this.paint();if(!this.started){this.started=true;this.exchange().catch(()=>{});this.schedule()}}
 paint(){const b=this.button;if(!b)return;b.innerHTML=icon(!this.muted)+`<span>${this.busy?'连接中':this.muted?'开麦':'关麦'}</span>`;b.dataset.voiceState=this.muted?'off':'on';b.setAttribute('aria-pressed',String(!this.muted));b.setAttribute('aria-label',this.muted?'打开麦克风，与同桌玩家聊天':'关闭麦克风');b.title=this.muted?'开启同桌语音':'麦克风已开启';b.disabled=!!this.busy}
 async toggle(){if(this.busy||!this.alive)return;this.busy=true;this.paint();try{
 if(!this.muted){this.muted=true;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.levels.remove(this.session);this.indicators();for(const p of this.peers.values())await p.sender?.replaceTrack(null);await this.exchange()}
 else{this.levels.resume();if(!navigator.mediaDevices?.getUserMedia||!globalThis.RTCPeerConnection)throw Error('当前浏览器暂不支持语音，请用最新版浏览器打开');const stream=await navigator.mediaDevices.getUserMedia(voiceCapture);if(!this.alive){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;this.muted=false;this.levels.bind(this.session,stream);this.indicators();for(const [id,p]of this.peers){if(p.pc.connectionState==='failed'){p.pc.close();p.audio.remove();this.levels.remove(id);this.peers.delete(id)}else{await p.sender?.replaceTrack(stream.getAudioTracks()[0]);await tuneVoiceSender(p.sender)}}for(const p of this.peers.values())p.audio.play().catch(()=>{});await this.exchange();if(!this.timer)this.schedule()}
 }catch(e){this.muted=true;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.rooms.toast(e.name==='NotAllowedError'?'请允许麦克风权限后再开麦':e.message)}finally{this.busy=false;this.paint();this.indicators()}}
 schedule(){clearTimeout(this.timer);if(this.alive)this.timer=setTimeout(async()=>{try{await this.exchange()}catch(e){if(!this.failed){this.rooms.toast('语音连接暂时中断，正在重连');this.failed=true}}this.schedule()},1500)}
 async exchange(){if(this.exchanging||!this.alive)return;this.exchanging=true;try{const signal=this.out[0];const data=await this.rooms.api('/api/rooms/'+this.rooms.id+'/voice',{session:this.session,muted:this.muted,...(signal?{signal}:{})});if(!this.alive)return;if(signal)this.out.shift();this.failed=false;this.members=data.members;this.indicators();const members=data.members.filter(m=>m.session!==this.session);const live=new Set(members.map(m=>m.session));for(const [id,p]of this.peers)if(!live.has(id)){p.pc.close();p.audio.remove();this.levels.remove(id);this.peers.delete(id)}for(const m of members)if(!this.peers.has(m.session)){const p=this.peer(m.session);if(this.session<m.session){const offer=await p.pc.createOffer();await p.pc.setLocalDescription(voiceDescription(offer));this.queue(m.session,{type:'offer',sdp:p.pc.localDescription.sdp})}}for(const message of data.messages){if(this.seen.has(message.id))continue;const p=this.peers.get(message.from);if(!p)continue;const v=message.payload;if(v.type==='candidate'){if(p.pc.remoteDescription)await p.pc.addIceCandidate(v.candidate);else p.candidates.push(v.candidate)}else{await p.pc.setRemoteDescription({type:v.type,sdp:v.sdp});if(v.type==='offer'){const transceiver=p.pc.getTransceivers().find(t=>t.mid!==null);if(transceiver){transceiver.direction='sendrecv';preferVoiceCodec(transceiver);p.sender=transceiver.sender;await p.sender.replaceTrack(this.stream?.getAudioTracks()[0]??null)}}for(const c of p.candidates.splice(0))await p.pc.addIceCandidate(c);if(v.type==='offer'){await p.pc.setLocalDescription(voiceDescription(await p.pc.createAnswer()));await tuneVoiceSender(p.sender);this.queue(message.from,{type:'answer',sdp:p.pc.localDescription.sdp})}else if(v.type==='answer')await tuneVoiceSender(p.sender)}this.seen.add(message.id)}if(this.seen.size>600)this.seen=new Set([...this.seen].slice(-400));}catch(e){if(e.message?.includes('对方已离开语音'))this.out.shift();throw e}finally{this.exchanging=false}}
 peer(id){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.cloudflare.com:3478'}]}),audio=document.createElement('audio');audio.autoplay=true;audio.setAttribute('playsinline','');audio.hidden=true;document.body.append(audio);const p={pc,audio,candidates:[],sender:this.session<id?pc.addTransceiver(this.stream?.getAudioTracks()[0]??'audio',{direction:'sendrecv'}).sender:null};for(const transceiver of pc.getTransceivers())preferVoiceCodec(transceiver);pc.onicecandidate=e=>{if(e.candidate)this.queue(id,{type:'candidate',candidate:e.candidate.toJSON()})};pc.ontrack=e=>{audio.srcObject=e.streams[0]??new MediaStream([e.track]);this.levels.bind(id,audio.srcObject);audio.play().catch(()=>this.rooms.toast('请点一下麦克风按钮以启用语音播放'))};pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected')tuneVoiceSender(p.sender);if(pc.connectionState==='failed')this.rooms.toast('部分玩家语音未连接，请关闭麦克风后重新开启')};this.peers.set(id,p);return p}
 queue(to,payload){if(this.alive){this.out.push({id:uid(),to,payload});clearTimeout(this.flushTimer);this.flushTimer=setTimeout(()=>this.flush(),0)}}
 async flush(){if(!this.alive||!this.out.length)return;if(this.exchanging){this.flushTimer=setTimeout(()=>this.flush(),100);return}try{await this.exchange()}catch{}if(this.out.length)this.flushTimer=setTimeout(()=>this.flush(),200)}
 labels(host,r){this.host=host;this.r=r;this.indicators();if(!this.meterTimer)this.meterTimer=setInterval(()=>{if(!document.hidden)this.indicators()},150)}
 indicators(){if(!this.host||!this.r)return;for(let i=0;i<this.r.seats.length;i++){const own=i===this.r.you,seat=this.r.seats[i],member=own?{session:this.session,muted:this.muted}:this.members.find(m=>m.id===seat.id),relative=(i-this.r.you+this.r.seats.length)%this.r.seats.length;const label=own?this.host.querySelector('.mp-own > strong'):this.host.querySelector(`[data-seat-label="${relative}"] > strong`);if(!label)continue;let meter=label.querySelector('[data-voice-meter]');if(!member||member.muted){meter?.remove();continue}if(!meter){if(!own&&label.firstChild?.nodeType===3){const name=document.createElement('span');name.className='voice-player-name';name.textContent=label.firstChild.textContent;label.firstChild.replaceWith(name)}meter=document.createElement('span');meter.dataset.voiceMeter=seat.id;meter.className='mp-voice-meter';meter.innerHTML='<span class="voice-dot"></span><i></i><i></i><i></i>';label.append(meter)}const peer=this.peers.get(member.session),source=peer?.pc.getReceivers().find(x=>x.track?.kind==='audio')?.getSynchronizationSources?.()[0];const volume=source?.audioLevel??this.levels.level(member.session);meter.dataset.speaking=String(volume>.015);meter.title=volume>.015?'正在说话':'麦克风已开启';meter.setAttribute('aria-label',meter.title);const bars=meter.querySelectorAll('i');for(let j=0;j<bars.length;j++)bars[j].style.height=Math.round(3+Math.min(1,volume*7)*[7,12,9][j])+'px'} }
 destroy(){if(!this.alive)return;this.alive=false;clearTimeout(this.timer);clearTimeout(this.flushTimer);clearInterval(this.meterTimer);this.levels.destroy();this.stream?.getTracks().forEach(t=>t.stop());for(const p of this.peers.values()){p.pc.close();p.audio.srcObject=null;p.audio.remove()}this.peers.clear();window.removeEventListener('pagehide',this.pagehide);if(this.timer)fetch('/api/rooms/'+this.rooms.id+'/voice',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:this.session,leave:true}),keepalive:true}).catch(()=>{})}
}
export function voiceButton(){return `<button type="button" class="mp-voice-button" data-room-mic aria-pressed="false" aria-label="打开麦克风，与同桌玩家聊天">${icon(false)}<span>开麦</span></button>`}
